/*
 * A257705  Sequence (a(n)) generated by Rule 1 (in Comments) with a(1) = 0
 *          and d(1) = 0.
 * https://oeis.org/A257705
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 186, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A257705:  computed by Rule 1 with a(1)=0, d(1)=0
   (see OEIS entry for the definition). */

#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

/* ---------- helper: ensure a boolean array has room for indices < needed ---------- */
static void ensure_bool_cap(bool **arr, size_t *cap, size_t needed)
{
    if (*cap == 0) {
        *cap = 16;
    }
    if (needed < *cap)
        return;
    size_t newcap = *cap;
    while (newcap <= needed)
        newcap <<= 1;
    bool *tmp = (bool *)realloc(*arr, newcap * sizeof(bool));
    if (!tmp)
        exit(1);
    memset(tmp + *cap, 0, (newcap - *cap) * sizeof(bool));
    *arr = tmp;
    *cap = newcap;
}

/* ---------- helper: ensure a seq_t array has room for indices < needed ---------- */
static void ensure_seq_cap(seq_t **arr, size_t *cap, size_t needed)
{
    if (*cap == 0) {
        *cap = 64;
    }
    if (needed < *cap)
        return;
    size_t newcap = *cap;
    while (newcap <= needed)
        newcap <<= 1;
    seq_t *tmp = (seq_t *)realloc(*arr, newcap * sizeof(seq_t));
    if (!tmp)
        exit(1);
    *arr = tmp;
    *cap = newcap;
}

/* ---------- static state ----------------------------------------------------- */
static seq_t *global_a_seq   = NULL;   /* a-values, a_seq[i] = a(i+1) */
static size_t global_a_cap   = 0;
static size_t global_a_len   = 0;

static bool *global_pos_used = NULL;   /* positive d’s, index = h (>0)   */
static size_t global_pos_cap = 0;
static bool *global_neg_used = NULL;   /* negative d’s, indexed by |h| */
static size_t global_neg_cap = 0;

/* ---------- helper: linear search for a value in the generated a-sequence ----- */
static bool a_seq_has(seq_t val)
{
    for (size_t i = 0; i < global_a_len; ++i)
        if (global_a_seq[i] == val)
            return true;
    return false;
}

/* ---------- main function ---------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)-1;   /* undefined – never called for n=0 */

    /* one‑time initialisation */
    if (global_a_seq == NULL) {
        /* initial a(1)=0 */
        global_a_cap   = 64;
        global_a_seq   = (seq_t *)malloc(global_a_cap * sizeof(seq_t));
        if (!global_a_seq)
            exit(1);
        global_a_seq[0] = (seq_t)0;
        global_a_len   = 1;

        /* initialise used‑arrays */
        global_pos_cap = 16;
        global_pos_used = (bool *)malloc(global_pos_cap * sizeof(bool));
        if (!global_pos_used)
            exit(1);
        memset(global_pos_used, 0, global_pos_cap * sizeof(bool));
        /* d(1)=0 is used, but we never query index 0 */
        global_pos_used[0] = true;

        global_neg_cap = 16;
        global_neg_used = (bool *)malloc(global_neg_cap * sizeof(bool));
        if (!global_neg_used)
            exit(1);
        memset(global_neg_used, 0, global_neg_cap * sizeof(bool));
    }

    /* generate terms until we have a(n) */
    while (global_a_len < n) {
        seq_t a_cur = global_a_seq[global_a_len - 1];

        int64_t chosen_h = 0;
        bool found = false;

        /* ---------- Step 1: try negative h (closest to zero) ----------------- */
        int64_t a_cur_int = (int64_t)a_cur;          /* non–negative */
        int64_t max_abs = (a_cur_int >= 3) ? (a_cur_int - 2) : 0; /* |h| max */

        /* make sure neg_used has room */
        ensure_bool_cap(&global_neg_used, &global_neg_cap, max_abs);

        for (int64_t abs = 1; abs <= max_abs; ++abs) {
            if (!global_neg_used[abs]) {
                seq_t cand = a_cur - (seq_t)abs;   /* a_cur + (-abs) */
                if (!a_seq_has(cand)) {
                    chosen_h = -abs;
                    found = true;
                    break;                          /* greatest such h */
                }
            }
        }

        /* ---------- Step 2: otherwise least positive h --------------------- */
        if (!found) {
            int64_t h_int = 1;
            while (true) {
                ensure_bool_cap(&global_pos_used, &global_pos_cap, h_int);
                if (!global_pos_used[h_int]) {
                    seq_t cand = a_cur + (seq_t)h_int;
                    if (!a_seq_has(cand)) {
                        chosen_h = h_int;
                        found = true;
                        break;
                    }
                }
                ++h_int;
            }
        }

        /* ---------- Mark the chosen d in the used‑array --------------------- */
        if (chosen_h > 0) {
            size_t hidx = (size_t)chosen_h;
            ensure_bool_cap(&global_pos_used, &global_pos_cap, hidx);
            global_pos_used[hidx] = true;
        } else {
            size_t abs = (size_t)(-chosen_h);
            ensure_bool_cap(&global_neg_used, &global_neg_cap, abs);
            global_neg_used[abs] = true;
        }

        /* ---------- Compute the next a(k+1) -------------------------------- */
        seq_t a_next;
        if (chosen_h >= 0)          /* simplest case */
            a_next = a_cur + (seq_t)chosen_h;
        else                       /* subtraction, avoid unsigned wrap */
            a_next = a_cur - (seq_t)(-chosen_h);

        /* store the new value */
        ensure_seq_cap(&global_a_seq, &global_a_cap, global_a_len);
        global_a_seq[global_a_len++] = a_next;
    }

    return global_a_seq[n - 1];
}
